// === Tab: mySketch.js ===
// ============================================
// BIG BANG SOLAR SYSTEM - CORRECTED
// Fixed camera controls and all features
// ============================================

// ============================================
// SHADER DEFINITIONS
// ============================================

const VERT_SHADER = `
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute float aSize;
    attribute vec3 aColor;
    attribute float aOffset;

    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform float uTime;

    varying vec3 vColor;
    varying float vAlpha;
    varying vec2 vUv;

    void main() {
        vUv = aTexCoord;
        vColor = aColor;

        vec3 pos = aPosition;
        float wave = sin(uTime * 0.5 + pos.x * 2.0 + pos.y * 3.0 + pos.z * 2.0) * 0.3;
        pos += aNormal * wave * 0.2;
        pos += aNormal * aOffset * 0.5;

        vec4 viewPos = uModelViewMatrix * vec4(pos, 1.0);
        float size = aSize * (300.0 / -viewPos.z);
        gl_PointSize = size;

        vAlpha = 0.8 + 0.2 * sin(uTime * 2.0 + pos.x * 5.0);
        gl_Position = uProjectionMatrix * viewPos;
    }
`;

const FRAG_SHADER = `
    precision highp float;

    varying vec3 vColor;
    varying float vAlpha;
    varying vec2 vUv;

    uniform float uTime;
    uniform vec3 uLightDir;

    void main() {
        vec2 center = gl_PointCoord - vec2(0.5);
        float dist = length(center);

        if (dist > 0.5) discard;

        float alpha = 1.0 - smoothstep(0.3, 0.5, dist);
        alpha *= vAlpha;

        vec3 color = vColor;
        float light = 0.5 + 0.5 * dot(vec3(0.0, 0.0, 1.0), normalize(uLightDir));
        color *= light;

        float glow = exp(-dist * 6.0) * 0.3;
        color += vec3(1.0, 0.8, 0.6) * glow;

        gl_FragColor = vec4(color, alpha * 0.9);
    }
`;

// ============================================
// ANIMATION STATE
// ============================================

const STATE = {
    BIG_BANG: 0,
    FORMATION: 1,
    ORBITING: 2,
    COMPLETE: 3
};

let state = STATE.BIG_BANG;
let progress = 0;
let bigBangParticles = [];
let formationProgress = 0;
let orbitStartDelay = 0;
let trails = [];
let trackAlpha = 0;

// ============================================
// GLOBAL VARIABLES
// ============================================

let planets = [];
let sun;
let cameraAngle = 0;
let starField = [];
let particleShader;
let zoomLevel = 350;
let cameraTargetY = 60;
let isAnimating = true;

// ============================================
// SETUP
// ============================================

function setup() {
    createCanvas(windowWidth, windowHeight, WEBGL);

    particleShader = createShader(VERT_SHADER, FRAG_SHADER);
    starField = createStarField();
    sun = new Sun(0, 0, 0, 40, [1.0, 0.9, 0.3]);

    const planetData = [
        { name: 'Mercury', radius: 50, size: 5, color: [0.7, 0.7, 0.7], speed: 0.025, particles: 200 },
        { name: 'Venus', radius: 75, size: 8, color: [1.0, 0.8, 0.4], speed: 0.018, particles: 300 },
        { name: 'Earth', radius: 105, size: 10, color: [0.2, 0.5, 0.9], speed: 0.014, particles: 400 },
        { name: 'Mars', radius: 135, size: 7, color: [0.8, 0.3, 0.1], speed: 0.011, particles: 250 },
        { name: 'Jupiter', radius: 180, size: 22, color: [0.8, 0.7, 0.5], speed: 0.008, particles: 600 },
        { name: 'Saturn', radius: 230, size: 18, color: [0.9, 0.8, 0.4], speed: 0.006, particles: 500, rings: true },
        { name: 'Uranus', radius: 280, size: 13, color: [0.6, 0.8, 0.9], speed: 0.0045, particles: 350 },
        { name: 'Neptune', radius: 325, size: 12, color: [0.2, 0.2, 0.8], speed: 0.0035, particles: 300 }
    ];

    for (let data of planetData) {
        let planet = new Planet(data);
        planet.x = random(-200, 200);
        planet.z = random(-200, 200);
        planet.angle = random(TWO_PI);
        planets.push(planet);
        trails[planet.name] = [];
    }

    generateBigBangParticles();
}

// ============================================
// BIG BANG PARTICLE GENERATION
// ============================================

function generateBigBangParticles() {
    for (let i = 0; i < 2000; i++) {
        let theta = random(TWO_PI);
        let phi = acos(2 * random(1) - 1);
        let speed = random(100, 300);
        let colorChoice = random();
        let col;

        if (colorChoice < 0.3) col = [1.0, 0.8, 0.2];
        else if (colorChoice < 0.6) col = [1.0, 0.4, 0.1];
        else if (colorChoice < 0.8) col = [0.8, 0.2, 0.5];
        else col = [0.2, 0.5, 1.0];

        bigBangParticles.push({
            pos: createVector(0, 0, 0),
            vel: createVector(
                speed * sin(phi) * cos(theta),
                speed * sin(phi) * sin(theta) * 0.5,
                speed * cos(phi)
            ),
            target: createVector(
                random(-200, 200),
                random(-100, 100),
                random(-200, 200)
            ),
            color: col,
            size: random(2, 6),
            life: 1,
            isPlanetParticle: false
        });
    }
}

// ============================================
// DRAW
// ============================================

function draw() {
    background(0);

    updateCamera();

    ambientLight(80);
    directionalLight(255, 255, 255, 0, 1, -0.5);
    pointLight(255, 255, 200, 0, 0, 0);

    drawStarField();
    updateAnimation();

    if (state === STATE.BIG_BANG) {
        drawBigBang();
    } else if (state === STATE.FORMATION) {
        drawFormation();
    } else {
        drawSolarSystem();
    }

    drawUI();
}

// ============================================
// ANIMATION UPDATE
// ============================================

function updateAnimation() {
    progress += 0.002;

    switch(state) {
        case STATE.BIG_BANG:
            if (progress > 1.5) {
                state = STATE.FORMATION;
                progress = 0;
                convertToPlanetParticles();
            }
            break;

        case STATE.FORMATION:
            formationProgress += 0.005;
            for (let planet of planets) {
                let targetX = planet.radius * cos(planet.angle);
                let targetZ = planet.radius * sin(planet.angle);
                planet.x = lerp(planet.x, targetX, 0.02);
                planet.z = lerp(planet.z, targetZ, 0.02);
            }
            sun.size = lerp(sun.size, 40, 0.02);

            if (formationProgress > 1.0) {
                state = STATE.ORBITING;
                orbitStartDelay = 0;
            }
            break;

        case STATE.ORBITING:
            orbitStartDelay += 0.005;
            for (let planet of planets) {
                let speedFactor = constrain(orbitStartDelay * 2, 0, 1);
                planet.speed = planet.baseSpeed * speedFactor;
                planet.update();

                if (frameCount % 2 === 0 && planet.speed > 0.001) {
                    trails[planet.name].push({
                        x: planet.x,
                        z: planet.z,
                        life: 255
                    });
                    if (trails[planet.name].length > 100) {
                        trails[planet.name].shift();
                    }
                }
                for (let t of trails[planet.name]) {
                    t.life -= 2;
                }
                trails[planet.name] = trails[planet.name].filter(t => t.life > 0);
            }

            if (orbitStartDelay > 0.5) {
                trackAlpha = lerp(trackAlpha, 255, 0.01);
                if (trackAlpha > 254) {
                    state = STATE.COMPLETE;
                }
            }
            break;

        case STATE.COMPLETE:
            for (let planet of planets) {
                planet.speed = planet.baseSpeed;
                planet.update();

                if (frameCount % 2 === 0) {
                    trails[planet.name].push({
                        x: planet.x,
                        z: planet.z,
                        life: 255
                    });
                    if (trails[planet.name].length > 100) {
                        trails[planet.name].shift();
                    }
                }
                for (let t of trails[planet.name]) {
                    t.life -= 2;
                }
                trails[planet.name] = trails[planet.name].filter(t => t.life > 0);
            }
            trackAlpha = 255;
            break;
    }
}

function convertToPlanetParticles() {
    for (let i = 0; i < bigBangParticles.length; i++) {
        let p = bigBangParticles[i];
        p.target = createVector(random(-100, 100), random(-50, 50), random(-100, 100));
        p.life = 1;
    }
}

// ============================================
// DRAW FUNCTIONS FOR EACH STATE
// ============================================

function drawBigBang() {
    push();
    for (let p of bigBangParticles) {
        p.pos.add(p.vel);
        p.vel.mult(0.995);
        p.life -= 0.001;

        if (p.life > 0) {
            push();
            translate(p.pos.x, p.pos.y, p.pos.z);
            noStroke();
            fill(p.color[0] * 255, p.color[1] * 255, p.color[2] * 255, p.life * 255);
            sphere(p.size * p.life);
            pop();
        }
    }
    pop();

    push();
    noStroke();
    fill(255, 255, 255, 100 * (1 - progress / 1.5));
    sphere(20);
    pop();
}

function drawFormation() {
    for (let planet of planets) {
        push();
        translate(planet.x, 0, planet.z);

        let scaleFactor = formationProgress;
        for (let p of planet.particles) {
            let pos = p.pos.copy().mult(planet.size * scaleFactor);
            push();
            translate(pos);
            noStroke();
            fill(p.color[0] * 255, p.color[1] * 255, p.color[2] * 255, 200 * scaleFactor);
            sphere(p.size * 0.8 * scaleFactor);
            pop();
        }
        pop();
    }

    sun.size = 40 * formationProgress;
    sun.display();
}

function drawSolarSystem() {
    drawTracks();

    for (let planet of planets) {
        drawTrail(planet);
    }

    for (let planet of planets) {
        planet.display();
    }

    sun.display();
}

// ============================================
// TRACK DRAWING
// ============================================

function drawTracks() {
    if (trackAlpha < 5) return;

    push();
    noFill();
    for (let planet of planets) {
        stroke(100, 150, 255, trackAlpha * 0.3);
        strokeWeight(1.5);
        ellipse(0, 0, planet.radius * 2, planet.radius * 2);

        stroke(100, 150, 255, trackAlpha * 0.1);
        strokeWeight(3);
        ellipse(0, 0, planet.radius * 2 + 5, planet.radius * 2 + 5);
    }
    pop();
}

// ============================================
// TRAIL DRAWING
// ============================================

function drawTrail(planet) {
    let trail = trails[planet.name];
    if (trail.length < 2) return;

    push();
    noFill();
    for (let i = 0; i < trail.length; i++) {
        let t = trail[i];
        let alpha = map(t.life, 0, 255, 0, 150);
        let size = map(t.life, 0, 255, 0.5, planet.size * 0.3);

        stroke(
            planet.color[0] * 200,
            planet.color[1] * 200,
            planet.color[2] * 200,
            alpha
        );
        strokeWeight(size);
        point(t.x, 0, t.z);
    }
    pop();
}

// ============================================
// CAMERA CONTROLS - FIXED!
// ============================================

function updateCamera() {
    let radius = zoomLevel;

    // Mouse interaction for full rotation
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
        let angleX = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -PI, PI);
        let angleY = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -PI/2.5, PI/2.5);
        // camera() with 9 parameters: (x, y, z, centerX, centerY, centerZ, upX, upY, upZ)
        camera(
            radius * sin(angleX) * cos(angleY),  // eye x
            radius * sin(angleY) + cameraTargetY, // eye y
            radius * cos(angleX) * cos(angleY),   // eye z
            0, 0, 0,  // center point (look at origin)
            0, 1, 0   // up direction (y-axis)
        );
    } else {
        cameraAngle += 0.002;
        camera(
            radius * sin(cameraAngle),  // eye x
            cameraTargetY,              // eye y
            radius * cos(cameraAngle),  // eye z
            0, 0, 0,  // look at origin
            0, 1, 0   // up direction
        );
    }

    perspective(60 * PI / 180, width/height, 0.1, 2000);
}

function mouseWheel(event) {
    zoomLevel = constrain(zoomLevel + event.delta * 0.3, 80, 800);
    return false;
}

// ============================================
// DRAWING HELPERS
// ============================================

function drawStarField() {
    push();
    translate(-width/2, -height/2, -800);
    noStroke();
    for (let star of starField) {
        let twinkle = 0.5 + 0.5 * sin(millis() / 1000 + star.x);
        fill(star.brightness * twinkle, star.brightness * twinkle, star.brightness * twinkle, star.alpha);
        ellipse(star.x, star.y, star.size, star.size);
    }
    pop();
}

function createStarField() {
    let stars = [];
    for (let i = 0; i < 500; i++) {
        stars.push({
            x: random(width * 1.5) - width * 0.25,
            y: random(height * 1.5) - height * 0.25,
            size: random(0.5, 3),
            brightness: random(100, 255),
            alpha: random(100, 200)
        });
    }
    return stars;
}

function drawUI() {
    push();
    translate(0, -height/2 + 30, 0);
    noStroke();
    fill(255, 255, 255, 150);
    textAlign(CENTER, CENTER);
    textSize(12);
    textFont('Arial');

    let statusText = '';
    switch(state) {
        case STATE.BIG_BANG:
            statusText = '💥 BIG BANG! Particles forming...';
            break;
        case STATE.FORMATION:
            statusText = '🌀 Planets forming from particles...';
            break;
        case STATE.ORBITING:
            statusText = '🌍 Planets beginning to orbit...';
            break;
        case STATE.COMPLETE:
            statusText = '🌌 Solar System Complete! Drag to orbit • Scroll to zoom';
            break;
    }
    text(statusText, 0, 0);

    if (state !== STATE.COMPLETE) {
        let barWidth = 200;
        let barHeight = 4;
        let progressValue = 0;
        switch(state) {
            case STATE.BIG_BANG:
                progressValue = progress / 1.5;
                break;
            case STATE.FORMATION:
                progressValue = formationProgress;
                break;
            case STATE.ORBITING:
                progressValue = orbitStartDelay / 1.0;
                break;
        }
        translate(0, 25, 0);
        noFill();
        stroke(255, 255, 255, 50);
        strokeWeight(1);
        rect(-barWidth/2, -barHeight/2, barWidth, barHeight, 2);
        fill(255, 255, 255, 100);
        noStroke();
        rect(-barWidth/2, -barHeight/2, barWidth * constrain(progressValue, 0, 1), barHeight, 2);
    }
    pop();
}

// ============================================
// PLANET CLASS
// ============================================

class Planet {
    constructor(data) {
        this.name = data.name;
        this.radius = data.radius;
        this.size = data.size;
        this.color = data.color;
        this.baseSpeed = data.speed;
        this.speed = 0;
        this.particleCount = data.particles || 300;
        this.hasRings = data.rings || false;
        this.angle = random(TWO_PI);
        this.x = 0;
        this.z = 0;

        this.particles = this.generateParticles();
    }

    generateParticles() {
        let pts = [];
        for (let i = 0; i < this.particleCount; i++) {
            var phi = acos(1 - 2 * (i + 0.5) / this.particleCount);
            var theta = PI * (1 + sqrt(5)) * i;

            let x = sin(phi) * cos(theta);
            let y = sin(phi) * sin(theta);
            let z = cos(phi);

            pts.push({
                pos: createVector(x, y, z),
                size: random(0.5, 1.5),
                offset: random(-0.15, 0.15),
                color: [
                    constrain(this.color[0] + random(-0.15, 0.15), 0, 1),
                    constrain(this.color[1] + random(-0.15, 0.15), 0, 1),
                    constrain(this.color[2] + random(-0.15, 0.15), 0, 1)
                ]
            });
        }
        return pts;
    }

    update() {
        this.angle += this.speed;
        this.x = this.radius * cos(this.angle);
        this.z = this.radius * sin(this.angle);
    }

    display() {
        push();
        translate(this.x, 0, this.z);

        for (let p of this.particles) {
            var pos = p.pos.copy().mult(this.size);

            push();
            translate(pos);

            shader(particleShader);

            particleShader.setUniform('uTime', millis() / 1000);
            particleShader.setUniform('uLightDir', [0.5, 1.0, 0.3]);

            stroke(p.color[0] * 255, p.color[1] * 255, p.color[2] * 255, 200);
            strokeWeight(p.size * 3);
            point(0, 0);

            resetShader();

            pop();
        }

        if (this.hasRings && state !== STATE.BIG_BANG) {
            this.drawRings();
        }

        if (state === STATE.COMPLETE || state === STATE.ORBITING) {
            this.drawLabel();
        }

        pop();
    }

    drawRings() {
        push();
        rotateX(PI / 2.5);
        noFill();
        for (let i = 0; i < 3; i++) {
            let ringSize = this.size * (2.0 + i * 0.6);
            var alpha = map(i, 0, 2, 150, 50);
            let weight = map(i, 0, 2, 4, 1.5);
            stroke(this.color[0] * 255, this.color[1] * 255, this.color[2] * 255, alpha);
            strokeWeight(weight);
            ellipse(0, 0, ringSize, ringSize);
        }
        pop();
    }

    drawLabel() {
        push();
        translate(0, -this.size - 18, 0);
        noStroke();
        fill(255, 255, 255, 150);
        textAlign(CENTER, CENTER);
        textSize(11);
        textFont('Arial');
        text(this.name, 0, 0);
        pop();
    }
}

// ============================================
// SUN CLASS
// ============================================

class Sun {
    constructor(x, y, z, size, color) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.size = size;
        this.color = color;
        this.particles = this.generateParticles();
        this.glowParticles = this.generateGlowParticles();
    }

    generateParticles() {
        var pts = [];
        for (let i = 0; i < 500; i++) {
            var phi = acos(1 - 2 * (i + 0.5) / 500);
            var theta = PI * (1 + sqrt(5)) * i;
            var x = sin(phi) * cos(theta);
            var y = sin(phi) * sin(theta);
            var z = cos(phi);
            pts.push({
                pos: createVector(x, y, z),
                size: random(0.5, 2.5),
                offset: random(-0.2, 0.2)
            });
        }
        return pts;
    }

    generateGlowParticles() {
        var pts = [];
        for (let i = 0; i < 150; i++) {
            var phi = acos(1 - 2 * (i + 0.5) / 150);
            var theta = PI * (1 + sqrt(5)) * i;
            let r = random(1.0, 1.8);
            var x = r * sin(phi) * cos(theta);
            var y = r * sin(phi) * sin(theta);
            var z = r * cos(phi);
            pts.push({
                pos: createVector(x, y, z),
                size: random(1, 4),
                alpha: random(20, 100)
            });
        }
        return pts;
    }

    display() {
        push();
        translate(this.x, this.y, this.z);

        for (let i = 8; i > 0; i--) {
            let glowSize = this.size + i * 30;
            var alpha = map(i, 0, 8, 30, 2);
            noStroke();
            fill(this.color[0] * 255, this.color[1] * 255, this.color[2] * 255, alpha);
            sphere(glowSize);
        }

        for (let p of this.glowParticles) {
            push();
            var pos = p.pos.copy().mult(this.size * 1.3);
            translate(pos);
            noStroke();
            var alpha = p.alpha * (0.5 + 0.5 * sin(millis() / 1000 + p.pos.x * 10));
            fill(255, 220, 100, alpha);
            sphere(p.size * 1.5);
            pop();
        }

        for (let p of this.particles) {
            push();
            var pos = p.pos.copy().mult(this.size * 0.85);
            translate(pos);
            noStroke();
            let brightness = 200 + random(55);
            fill(255, 220 + random(35), 80 + random(40), 220);
            sphere(p.size * 1.5);
            pop();
        }

        push();
        for (let i = 0; i < 50; i++) {
            var theta = random(TWO_PI);
            var phi = random(PI);
            var r = this.size * 0.7 + random(this.size * 0.3);
            var x = r * sin(phi) * cos(theta);
            var y = r * sin(phi) * sin(theta);
            var z = r * cos(phi);
            fill(255, 230, 150, 40 + random(60));
            noStroke();
            push();
            translate(x, y, z);
            sphere(3 + random(8));
            pop();
        }
        pop();

        push();
        noStroke();
        fill(255, 240, 200, 50);
        sphere(this.size * 0.5);
        pop();

        pop();
    }
}

// ============================================
// WINDOW RESIZE
// ============================================

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}

